#include <AccelStepper.h>

const float STEPS = 2037.8864;  // steps per turn: 32 steps × a 63.68:1 gearbox
const int SEGMENTS = 8;
const int BUTTON = 2;
const int DIR = 1;  // 1 = clockwise, −1 = anticlockwise
// the driver's IN1-IN4 on D8-D11, given in the order 8, 10, 9, 11 so the coils fire in sequence
AccelStepper wheel(AccelStepper::FULL4WIRE, 8, 10, 9, 11);

const char* PRIZES[] = {"50", "100", "200", "AGAIN",
                        "500", "x2", "1000", "JACKPOT"};
int at = 0;       // the segment under the pointer now
long moved = 0;   // segments travelled since power-on

void setup() {
  pinMode(BUTTON, INPUT);
  wheel.setMaxSpeed(15 * STEPS / 60.0);  // turns per minute → steps per second
  wheel.setAcceleration(1200);
  Serial.begin(9600);
  randomSeed(analogRead(A0));
  Serial.println("Press the button to spin the wheel!");
}

void loop() {
  if (digitalRead(BUTTON) == HIGH) {
    int prize = random(SEGMENTS);
    int ahead = DIR > 0 ? (prize - at + SEGMENTS) % SEGMENTS : (at - prize + SEGMENTS) % SEGMENTS;
    moved += 1 * SEGMENTS + ahead;
    // round only once, from the running total, so the error never adds up
    long target = round(moved * STEPS / SEGMENTS);
    wheel.moveTo(DIR * target);
    wheel.runToPosition();  // blocks until the wheel has stopped
    at = prize;
    Serial.print("Landed on: ");
    Serial.println(PRIZES[at]);
  }
}
